INSERT INTO packages (id, scheme_version_id, speciality_code, speciality_name, package_code, package_name, treatment_code, treatment_name, package_amount, rate_tier, los_days, implant_criteria, stratification_criteria, icd_code) VALUES
('pkg1a063ad3f306nfxlr', 'sv1a063ad3f2biq3owp', 'M2', 'Pediatric Medicine', '', '', '24.98', 'CRRT (per session)', 8000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30p66w3w', 'sv1a063ad3f2biq3owp', 'M2', 'Pediatric Medicine', '', '', '24.99', 'Blood and blood component transfusion up to a limit of 2 days(admission for a diagnostic procedure leading to treatment requiring admission, e.g. bone marrow and bone biopsy, endoscopy, liver biopsy, bronchoscopy, CT/MRI under GA, broncho- alveolar lavage, lumbar puncture, muscle biopsy, FNAC, pleural aspiration, ascitic tapping, neostigmine challenge test etc.)Package rate per Day', 1500, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30ckhy5y', 'sv1a063ad3f2biq3owp', 'M2', 'Pediatric Medicine', '', '', '24.100', 'Blood and blood component transfusion for indications like Thalassemia/Hemoglobinopathies - upto a limit of 2 days,Package rate per Day', 1500, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30qqcrtk', 'sv1a063ad3f2biq3owp', 'M2', 'Pediatric Medicine', '', '', '24.101', 'High end radiological diagnostic (CT, MRI, Imaging including nuclear imaging) - can only be clubbed with medical package.', 5000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f308u3eo6', 'sv1a063ad3f2biq3owp', 'M2', 'Pediatric Medicine', '', '', '24.102', 'High end histopathology (Biopsies) and advanced serology investigations - can only be clubbed with medical package.', 5000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30jqnq4o', 'sv1a063ad3f2biq3owp', 'Cluster - 25 NEO-NATAL PACKAGES', 'Cluster - 25 NEO-NATAL PACKAGES', '', '', 'Cluster - 25 NEO-NATAL PACKAGES', 'Cluster - 25 NEO-NATAL PACKAGES', 25, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30zqn5yc', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.1', 'Basic neonatal care package (Rs. 500 per day, maximum 1500): Babies that can be managed by side of mother in postnatal ward without requiring admission in SNCU/NICU: • Any newborn needing feeding support • Babies requiring closer monitoring or short-term care for conditions like: o Birth asphyxia (need for positive pressure ventilation; no HIE) o Moderate jaundice requiring phototherapy o Large for dates (>97 percentile) Babies o Small for gestational age (less than 3rd centile) (Package rate is per day)', 500, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30k4qwzk', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.2', 'Special Neonatal Care Package (Rs. 3000 per day, maximum of 18000 - pre-auth after 4 days): Babies that required admission to SNCU or NICU: Babies admitted for short term care for conditions like: • Mild Respiratory Distress/tachypnea • Mild encephalopathy • Severe jaundice requiring intensive phototherapy • Haemorrhagic disease of newborn • Unwell baby requiring monitoring • Some dehydration • Hypoglycaemia Mother''s stay and food in the hospital for breastfeeding, family centred care and (Kangaroo Mother Care) KMC is mandatory and included in the package rate', 3000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30gm43r0', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.3', 'Intensive Neonatal Care Package (Rs. 5000 per day, maximum of Rs. 50,000 - pre- auth is needed after 5 days) (Package rate is per day) Babies with birthweight 1500-1799 g or Babies of any birthweight and at least one of the following conditions: • Need for mechanical ventilation for less than 24 hours or non-invasive respiratory support (CPAP, HFFNC) • Sepsis / pneumonia without complications • Hyperbilirubinemia requiring exchange transfusion • Seizures • Major congenital malformations (pre-surgical stabilization, not requiring ventilation) • Cholestasis significant enough requiring work up and in-hospital management • Congestive heart failure or shock Mother''s stay and food in the hospital for breastfeeding, family centred care and (Kangaroo Mother Care) KMC is mandatory and included in the package rate', 5000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f303utin1', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.4', 'Advanced Neonatal Care Package (Rs. 6000 per day, maximum of Rs. 75,000 - pre- auth is needed after 7 days) (Package rate is per day) Babies with birthweight of 1200-1499 g or Babies of any birthweight with at least one of the following conditions: • Any condition requiring invasive ventilation longer than 24 hours • Hypoxic Ischemic encephalopathy requiring Therapeutic Hypothermia • Cardiac rhythm disorders needing intervention (the cost of cardiac surgery or implant will be covered under cardiac surgery packages) • Sepsis with complications such as meningitis or bone and joint infection, DIC or shock • Renal failure requiring dialysis • Inborn errors of metabolism Mother''s stay and food in the hospital for breastfeeding, family centred care and (Kangaroo Mother Care) KMC is mandatory and included in the package rate', 6000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f303dp63u', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.5', 'Critical Care Neonatal Package (Rs. 7000 per day, maximum of Rs. 1,20,000 - pre- auth after 10 days) (Package rate is per day) Babies with birthweight of <1200 g or Babies of any birthweight with at least one of the following conditions: • Severe Respiratory Failure requiring High Frequency Ventilation or inhaled Nitric Oxide (iNO) • Multisystem failure requiring multiple organ support including mechanical ventilation and multiple inotropes • Critical congenital heart disease Mother''s stay and food in the hospital for breastfeeding, family centred care and (Kangaroo Mother Care) KMC is mandatory and included in the package rate', 7000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f301bkg7y', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.6', 'Chronic Care Package (Rs. 3000 per day, maximum of Rs. 30,000): If the baby requires stay beyond the upper limit of usual stay in Package no 0004 or 0005 for conditions like severe BPD requiring respiratory support, severe NEC requiring prolonged TPN support (Package rate is per day)', 3000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30hpxyoy', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.7', 'High Risk Newborn Post Discharge Care Package (Protocol Driven)', 2400, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30pw2ko6', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.8', 'Laser Therapy for Retinopathy of Prematurity (Irrespective of no. of eyes affected) - per session', 1500, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f304hpn7l', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.9', 'Advanced Surgery for Retinopathy of Prematurity', 15000, 'Package Rate', 0, '', '', ''),
('pkg1a063ad3f30lhjvev', 'sv1a063ad3f2biq3owp', 'M3', 'Neonatal', '', '', '25.10', 'Ventriculoperitoneal Shunt Surgery (VP) or Omaya Reservoir or External Drainage for Hydrocephalus', 5000, 'Package Rate', 0, '', '', ''),
